package com.hau.notification.application;import com.hau.notification.application.dto.IncomingEvent;import com.hau.notification.application.port.out.*;import com.hau.notification.application.service.EventNotificationService;import com.hau.notification.domain.model.*;import com.hau.notification.domain.repository.NotificationRepository;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class EventNotificationServiceTest{
 @Test void otpUsesEmailOnlyAndDuplicateIsSkipped(){var r=mock(NotificationRepository.class);var inbox=mock(ProcessedEventStore.class);var ws=mock(RealtimeNotifier.class);var mail=mock(EmailSender.class);UUID id=UUID.randomUUID();var s=new EventNotificationService(r,inbox,ws,mail,Clock.systemUTC());var e=new IncomingEvent(id,"PASSWORD_RESET_OTP_REQUESTED",UUID.randomUUID(),Map.of("email","u@hau.edu.vn","otp","123456"));assertThat(s.handle(e)).isTrue();verify(mail).send("u@hau.edu.vn","Password reset OTP","123456");verifyNoInteractions(r,ws);when(inbox.exists(id)).thenReturn(true);assertThat(s.handle(e)).isFalse();verify(mail,times(1)).send(any(),any(),any());}
 @Test void questionApprovalPersistsBeforeRealtime(){var r=mock(NotificationRepository.class);var inbox=mock(ProcessedEventStore.class);var ws=mock(RealtimeNotifier.class);var mail=mock(EmailSender.class);when(r.save(any())).thenAnswer(i->i.getArgument(0));var order=inOrder(r,ws);var s=new EventNotificationService(r,inbox,ws,mail,Clock.systemUTC());s.handle(new IncomingEvent(UUID.randomUUID(),"QUESTION_APPROVED",UUID.randomUUID(),Map.of("userId",UUID.randomUUID().toString())));order.verify(r).save(any());order.verify(ws).send(any());verifyNoInteractions(mail);}
}
